    s = s.replace('\r\n', '\n')
    s = fn(s)
    if crlf:
        s = s.replace('\n', '\r\n')
    open(p, 'w', encoding='utf-8', newline='').write(s)

def rep(s, o, n, count=1):
    assert o in s, o[:70]
    return s.replace(o, n, count)

# ---- RestResource: Action Surge flag + Ki uses
def rr(s):
    s = rep(s, """	/** Barbarian Rage: a COUNT""", """	/** Fighter's Action Surge: once per short or long rest. */
