		if (empty != null) {
			guiGraphics.drawCenteredString(this.font, empty, this.width / 2, this.height / 2, GuiStyle.MUTED_COLOR);
		}

		super.render(guiGraphics, mouseX, mouseY, partialTicks);
	}
